commands.stdout:
{
  "name": "video-analyzer-e2e",
  "networks": {
    "backend": {
      "name": "video-analyzer-e2e_backend",
      "ipam": {},
      "internal": true
    },
    "ingress": {
      "name": "video-analyzer-e2e_ingress",
      "driver": "bridge",
      "ipam": {}
    }
  },
  "secrets": {
    "postgres_password": {
      "name": "video-analyzer-e2e_postgres_password",
      "file": "C:\\other-files\\video-analyzer\\.secrets\\postgres_password"
    },
    "redis_password": {
      "name": "video-analyzer-e2e_redis_password",
      "file": "C:\\other-files\\video-analyzer\\.secrets\\redis_password"
    }
  },
  "services": {
    "api": {
      "restart": "unless-stopped",
      "cap_drop": [
        "ALL"
      ],
      "cpus": 1,
      "command": null,
      "entrypoint": null,
      "image": "video-analyzer-backend:0.1.0",
      "init": true,
      "logging": {
        "driver": "json-file",
        "options": {
          "max-file": "3",
          "max-size": "10m"
        }
      },
      "mem_limit": "536870912",
      "networks": {
        "backend": null,
        "ingress": null
      },
      "pids_limit": 128,
      "read_only": true,
      "secrets": [
        {
          "source": "postgres_password",
          "target": "/run/secrets/postgres_password"
        },
        {
          "source": "redis_password",
          "target": "/run/secrets/redis_password"
        }
      ],
      "security_opt": [
        "no-new-privileges:true"
      ],
      "tmpfs": [
        "/tmp:size=64m,mode=1777"
      ],
      "user": "10001:10001",
      "volumes": [
        {
          "type": "volume",
          "source": "work_data",
          "target": "/data",
          "volume": {}
        }
      ],
      "build": {
        "context": "C:\\other-files\\video-analyzer\\backend",
        "dockerfile": "Dockerfile"
      },
      "depends_on": {
        "migrate": {
          "condition": "service_completed_successfully",
          "required": true
        },
        "redis": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "healthcheck": {
        "test": [
          "CMD",
          "python",
          "-c",
          "import urllib.request; urllib.request.urlopen('http://127.0.0.1:8000/api/v1/health/ready', timeout=6)"
        ],
        "timeout": "8s",
        "interval": "10s",
        "retries": 5,
        "start_period": "10s"
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 8000,
          "published": "17811",
          "protocol": "tcp"
        }
      ]
    },
    "frontend": {
      "restart": "unless-stopped",
      "cap_drop": [
        "ALL"
      ],
      "cpus": 1,
      "command": null,
      "entrypoint": null,
      "environment": {
        "API_INTERNAL_URL": "http://api:8000",
        "HOSTNAME": "0.0.0.0",
        "NEXT_TELEMETRY_DISABLED": "1",
        "PORT": "3100"
      },
      "image": "video-analyzer-frontend:0.1.0",
      "init": true,
      "logging": {
        "driver": "json-file",
        "options": {
          "max-file": "3",
          "max-size": "10m"
        }
      },
      "mem_limit": "536870912",
      "networks": {
        "ingress": null
      },
      "pids_limit": 128,
      "read_only": true,
      "security_opt": [
        "no-new-privileges:true"
      ],
      "tmpfs": [
        "/tmp:size=64m,mode=1777"
      ],
      "user": "10001:10001",
      "build": {
        "context": "C:\\other-files\\video-analyzer\\frontend",
        "dockerfile": "Dockerfile"
      },
      "depends_on": {
        "api": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "healthcheck": {
        "test": [
          "CMD",
          "node",
          "-e",
          "fetch('http://127.0.0.1:3100/health/live').then(r=\u003eprocess.exit(r.ok?0:1)).catch(()=\u003eprocess.exit(1))"
        ],
        "timeout": "5s",
        "interval": "10s",
        "retries": 5
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 3100,
          "published": "17810",
          "protocol": "tcp"
        }
      ]
    },
    "migrate": {
      "restart": "no",
      "cap_drop": [
        "ALL"
      ],
      "cpus": 1,
      "command": [
        "alembic",
        "upgrade",
        "head"
      ],
      "entrypoint": null,
      "image": "video-analyzer-backend:0.1.0",
      "init": true,
      "logging": {
        "driver": "json-file",
        "options": {
          "max-file": "3",
          "max-size": "10m"
        }
      },
      "mem_limit": "536870912",
      "networks": {
        "backend": null
      },
      "pids_limit": 128,
      "read_only": true,
      "secrets": [
        {
          "source": "postgres_password",
          "target": "/run/secrets/postgres_password"
        },
        {
          "source": "redis_password",
          "target": "/run/secrets/redis_password"
        }
      ],
      "security_opt": [
        "no-new-privileges:true"
      ],
      "tmpfs": [
        "/tmp:size=64m,mode=1777"
      ],
      "user": "10001:10001",
      "build": {
        "context": "C:\\other-files\\video-analyzer\\backend",
        "dockerfile": "Dockerfile"
      },
      "depends_on": {
        "postgres": {
          "condition": "service_healthy",
          "required": true
        }
      }
    },
    "postgres": {
      "restart": "unless-stopped",
      "cpus": 1,
      "command": null,
      "entrypoint": null,
      "environment": {
        "POSTGRES_DB": "video_analyzer",
        "POSTGRES_INITDB_ARGS": "--auth-host=scram-sha-256",
        "POSTGRES_PASSWORD_FILE": "/run/secrets/postgres_password",
        "POSTGRES_USER": "video_analyzer"
      },
      "image": "postgres:17.11-alpine@sha256:266d3c257594e195b309ae9d1805e54c788f1d7b375f56bf6c367aac6c917e7b",
      "logging": {
        "driver": "json-file",
        "options": {
          "max-file": "3",
          "max-size": "10m"
        }
      },
      "mem_limit": "536870912",
      "networks": {
        "backend": null
      },
      "pids_limit": 128,
      "secrets": [
        {
          "source": "postgres_password",
          "target": "/run/secrets/postgres_password"
        }
      ],
      "security_opt": [
        "no-new-privileges:true"
      ],
      "volumes": [
        {
          "type": "volume",
          "source": "postgres_data",
          "target": "/var/lib/postgresql/data",
          "volume": {}
        }
      ],
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "pg_isready -U video_analyzer -d video_analyzer"
        ],
        "timeout": "3s",
        "interval": "5s",
        "retries": 20
      }
    },
    "redis": {
      "restart": "unless-stopped",
      "cap_drop": [
        "ALL"
      ],
      "cpus": 0.5,
      "command": null,
      "entrypoint": [
        "/bin/sh",
        "/opt/start.sh"
      ],
      "image": "redis:7.2.13-alpine@sha256:9907ac0c435717b4d95697cb4d0ce77d100b1d21269a01a0ce66f27335184c38",
      "logging": {
        "driver": "json-file",
        "options": {
          "max-file": "3",
          "max-size": "10m"
        }
      },
      "mem_limit": "268435456",
      "networks": {
        "backend": null
      },
      "pids_limit": 64,
      "read_only": true,
      "secrets": [
        {
          "source": "redis_password",
          "target": "/run/secrets/redis_password"
        }
      ],
      "security_opt": [
        "no-new-privileges:true"
      ],
      "tmpfs": [
        "/tmp:size=16m,mode=1777"
      ],
      "user": "redis",
      "volumes": [
        {
          "type": "volume",
          "source": "redis_data",
          "target": "/data",
          "volume": {}
        },
        {
          "type": "bind",
          "source": "C:\\other-files\\video-analyzer\\infra\\redis\\start.sh",
          "target": "/opt/start.sh",
          "read_only": true,
          "bind": {}
        }
      ],
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "REDISCLI_AUTH=\"$$(cat /run/secrets/redis_password)\" redis-cli ping | grep -qx PONG"
        ],
        "timeout": "3s",
        "interval": "5s",
        "retries": 20
      }
    },
    "worker": {
      "restart": "unless-stopped",
      "cap_drop": [
        "ALL"
      ],
      "cpus": 1,
      "command": [
        "celery",
        "-A",
        "app.tasks.worker:celery_app",
        "worker",
        "--loglevel=WARNING",
        "--concurrency=1",
        "--hostname=infra@worker"
      ],
      "entrypoint": null,
      "image": "video-analyzer-backend:0.1.0",
      "init": true,
      "logging": {
        "driver": "json-file",
        "options": {
          "max-file": "3",
          "max-size": "10m"
        }
      },
      "mem_limit": "536870912",
      "networks": {
        "backend": null
      },
      "pids_limit": 128,
      "read_only": true,
      "secrets": [
        {
          "source": "postgres_password",
          "target": "/run/secrets/postgres_password"
        },
        {
          "source": "redis_password",
          "target": "/run/secrets/redis_password"
        }
      ],
      "security_opt": [
        "no-new-privileges:true"
      ],
      "tmpfs": [
        "/tmp:size=64m,mode=1777"
      ],
      "user": "10001:10001",
      "volumes": [
        {
          "type": "volume",
          "source": "work_data",
          "target": "/data",
          "volume": {}
        }
      ],
      "build": {
        "context": "C:\\other-files\\video-analyzer\\backend",
        "dockerfile": "Dockerfile"
      },
      "depends_on": {
        "migrate": {
          "condition": "service_completed_successfully",
          "required": true
        },
        "redis": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "healthcheck": {
        "test": [
          "CMD",
          "celery",
          "-A",
          "app.tasks.worker:celery_app",
          "inspect",
          "ping",
          "--destination=infra@worker",
          "--timeout=3"
        ],
        "timeout": "8s",
        "interval": "15s",
        "retries": 5,
        "start_period": "15s"
      }
    }
  },
  "volumes": {
    "postgres_data": {
      "name": "video-analyzer-e2e_postgres_data"
    },
    "redis_data": {
      "name": "video-analyzer-e2e_redis_data"
    },
    "work_data": {
      "name": "video-analyzer-e2e_work_data"
    }
  },
  "x-app": {
    "build": "./backend",
    "cap_drop": [
      "ALL"
    ],
    "cpus": 1,
    "image": "video-analyzer-backend:0.1.0",
    "init": true,
    "logging": {
      "driver": "json-file",
      "options": {
        "max-file": "3",
        "max-size": "10m"
      }
    },
    "mem_limit": "512m",
    "networks": [
      "backend"
    ],
    "pids_limit": 128,
    "read_only": true,
    "secrets": [
      "postgres_password",
      "redis_password"
    ],
    "security_opt": [
      "no-new-privileges:true"
    ],
    "tmpfs": [
      "/tmp:size=64m,mode=1777"
    ],
    "user": "10001:10001"
  }
}
